def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # Recent opponent behavior
    recent = history[-8:]
    rlen = len(recent)
    ropp_c = sum(1 for _, o in recent if o == 'C')
    ropp_d = rlen - ropp_c
    rme_c = sum(1 for m, _ in recent if m == 'C')

    # Global stats
    opp_c = sum(1 for _, o in history if o == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for m, _ in history if m == 'C')

    last_me, last_opp = history[-1]
    remaining = 100 - n

    # Current trailing defection streak of opponent
    opp_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run += 1
        else:
            break

    # Opponent's eventual response to our defections vs cooperations
    d_after_my_d = 0
    c_after_my_d = 0
    d_after_my_c = 0
    c_after_my_c = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]
        if pm == 'D':
            if co == 'D':
                d_after_my_d += 1
            else:
                c_after_my_d += 1
        else:
            if co == 'D':
                d_after_my_c += 1
            else:
                c_after_my_c += 1

    # Detect always-defect / sustained defect
    if n >= 6 and opp_c == 0:
        return 'D'

    # Detect always-cooperate: exploit heavily including early
    if n >= 5 and opp_d == 0:
        # Cooperate a bit at very start to avoid alarming, then exploit
        if n < 4:
            return 'C'
        return 'D'

    # Detect four_D_ALLC-like: they defect first four, then always cooperate
    if n >= 6 and opp_c == n - 4 and opp_d == 4:
        # Only exploit them at the tail
        if remaining <= 3:
            return 'D'
        return 'C'

    # Detect grim-trigger: after our first D, opponent always D
    first_my_d = -1
    for i in range(n):
        if history[i][0] == 'D':
            first_my_d = i
            break
    if first_my_d >= 0 and first_my_d < n - 3:
        after = history[first_my_d + 1:]
        if after and all(o == 'D' for _, o in after):
            return 'D'

    # Detect TFT-ish mimic: opponent's move often equals our previous move.
    # We use this to avoid the 1-D-recovery trap.
    if n >= 6:
        mimic = 0
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                mimic += 1
        mimic_frac = mimic / (n - 1)
        if mimic_frac > 0.72:
            # If they just defected, they are likely mirroring our previous D;
            # play C to break the cycle and restore mutual cooperation.
            if last_opp == 'D':
                # But if they seem to be punishing continuously, avoid feeding.
                if opp_run >= 3:
                    return 'D'
                return 'C'
            # If last was C, they mirrored our C; safe to C.
            if last_opp == 'C':
                # Near end exploit
                if remaining <= 3:
                    return 'D'
                return 'C'

    # Tail exploitation: if opponent is mostly cooperative, defect late.
    if remaining <= 3:
        if opp_c > n * 0.55:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'
    if remaining <= 6:
        if opp_c > n * 0.6:
            return 'D'
        if ropp_d >= 2:
            return 'D'
        return 'C'

    # Strongly cooperative: maintain CC, with rare late probes.
    if opp_c >= n - 1 or opp_c * 4 >= n * 3:
        if n > 10 and remaining <= 15 and n % 5 == 0:
            return 'D'
        if last_opp == 'D':
            # They rarely defect; punish once then cooperate
            return 'D'
        return 'C'

    # Mostly defective: punish hard but continue defecting (opponent is exploiter)
    if opp_c * 3 <= n:
        return 'D'

    # Since the "ten CC rounds then TFT" probe shows parent fails to recover
    # after its own D against TFT, we must be careful not to test-defect.
    # Against a cooperative-looking opponent past 10 rounds, just cooperate.
    if ropp_c >= rlen - 1 and n > 10:
        if last_opp == 'C':
            return 'C'
        else:
            return 'C' if rng.random() < 0.5 else 'D'

    # Opponent just cooperated after we defected: they may still be nice → C
    if last_opp == 'C' and last_me == 'D':
        if remaining > 5:
            return 'C'
        return 'C'

    # Opponent just defected
    if last_opp == 'D':
        if opp_run >= 3:
            return 'D'
        if opp_run == 2:
            # occasional forgiveness to restart cooperation
            return 'D' if rng.random() < 0.75 else 'C'
        # Single defection: respond with D, but forgive soon
        # Forgive if they were previously cooperative
        if opp_c * 2 >= n:
            return 'C' if rng.random() < 0.25 else 'D'
        return 'D'

    # Otherwise cooperate
    return 'C'
